<script lang="ts">
 let step=1; function next(){ if(step<3) step++; } function back(){ if(step>1) step--; }
</script><main class="shell"><header class="top"><a href="/register" style="color:white">Back</a><strong>Teacher signup</strong></header><form class="form"><div class="progress"><span style="width: {step/3*100}%"></span></div><h1>Step {step} of 3</h1>{#if step===1}<input class="input" placeholder="Email"/><input class="input" type="password" placeholder="Password"/><input class="input" type="password" placeholder="Confirm password"/>{:else if step===2}<input class="input" placeholder="Full name"/><input class="input" placeholder="Phone"/><select class="input"><option>County</option></select><input class="input" type="file" accept=".pdf,.jpg,.jpeg,.png"/><input class="input" placeholder="Subjects taught"/>{:else}<input class="input" placeholder="M-Pesa phone number"/><input class="input" inputmode="numeric" maxlength="6" placeholder="Email OTP"/><p class="muted">Submitting will call /api/auth/signup/teacher after OTP verification.</p>{/if}<div class="tabs"><button type="button" class="btn" on:click={back}>Back</button><button type="button" class="btn" on:click={next}>{step===3?'Submit':'Continue'}</button></div></form></main>
